import { useState, useEffect } from 'react';
import InvoiceTable from './InvoiceTable';

interface Invoice {
  id: number;
  number: string;
  customer: string;
  amount: number;
  status: 'paid' | 'pending' | 'overdue';
}

const mockData: Invoice[] = [
  { id: 1, number: 'INV-001', customer: 'Acme Corp', amount: 450.00, status: 'paid' },
  { id: 2, number: 'INV-002', customer: 'Beta Inc', amount: 230.50, status: 'pending' },
  { id: 3, number: 'INV-0-03', customer: 'Gamma Ltd', amount: 180.00, status: 'overdue' },
  { id: 4, number: 'INV-004', customer: 'Delta Group', amount: 320.75, status: 'paid' },
  { id: 5, number: 'INV-005', customer: 'Epsilon Co', amount: 550.25, status: 'pending' },
  { id: 6, number: 'INV-006', customer: 'Zeta Corp', amount: 780.00, status: 'overdue' },
  { id: 7, number: 'INV-007', customer: 'Omega Inc', amount: 300.00, status: 'paid' },
  { id: 8, number: 'INV-008', customer: 'Alpha Group', amount: 410.50, status: 'pending' },
];

export default function App() {
  const [invoices, setInvoices] = useState<Invoice[]>(mockData);
  const [sortConfig, setSortConfig] = useState<{ key: keyof Invoice; direction: 'ascending' | 'descending' | null }>({
    key: 'amount',
    direction: 'ascending',
  });

  useEffect(() => {
    let sorted = [...invoices];
    if (sortConfig.key !== null) {
      sorted.sort((a, b) => {
        if (a[sortConfig.key] < b[sortConfig.key]) {
          return sortConfig.direction === 'ascending' ? -1 : 1;
        }
        if (a[sortConfig.key] > b[sortConfig.key]) {
          return sortConfig.direction === 'ascending' ? 1 : -1;
        }
        return 0;
      });
    }
    setInvoices(sorted);
  }, [sortConfig, invoices]);

  const handleSort = (key: keyof Invoice) => {
    setSortConfig((prev) => {
      if (prev.key === key) {
        return {
          key,
          direction: prev.direction === 'ascending' ? 'descending' : 'ascending',
        };
      }
      return { key, direction: 'ascending' };
    });
  };

  return (
    <div className="min-h-screen p-6 bg-gray-50">
      <h1 className="text-2xl font-semibold text-gray-800 mb-6">Invoices</h1>
      <InvoiceTable
        invoices={invoices}
        onSort={handleSort}
        sortConfig={sortConfig}
      />
    </div>
  );
}
