### InvoiceTable.tsx
```tsx
import React from 'react';
import StatusBadge from './StatusBadge';

interface Invoice {
  id: number;
  number: string;
  customer: string;
  amount: number;
  status: 'paid' | 'pending' | 'overdue';
}

interface InvoiceTableProps {
  invoices: Invoice[];
  onSort: (key: keyof Invoice) => void;
  sortConfig: { key: keyof Invoice; direction: 'ascending' | 'descending' | null };
}

const InvoiceTable: React.FC<InvoiceTableProps> = ({ invoices, onSort, sortConfig }) => {
  const totalAmount = invoices.reduce((sum, invoice) => sum + invoice.amount, 0);

  const getSortIndicator = (key: keyof Invoice) => {
    if (sortConfig.key === key) {
      return sortConfig.direction === 'ascending' ? (
        <span className="w-4 h-4 text-gray-500">↑</span>
      ) : (
        <span className="w-4 h-4 text-gray-500">↓</span>
      );
    }
    return <span className="w-4 h-4 text-gray-300">↕</span>;
  };

  return (
    <div className="overflow-x-auto bg-white rounded-lg shadow-sm border border-gray-200">
      <table className="min-w-full divide-y divide-gray-200">
        <thead className="bg-gray-50">
          <tr>
            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-100" onClick={() => onSort('number')}>
              Number
              {getSortIndicator('number')}
            </th>
            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-100" onClick={() => onSort('customer')}>
              Customer
              {getSortIndicator('customer')}
            </th>
            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-100" onClick={() => onSort('amount')}>
              Amount
              {getSortIndicator('amount')}
            </th>
            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider cursor-pointer hover:bg-gray-100" onClick={() => onSort('status')}>
              Status
              {getSortIndicator('status')}
            </th>
          </tr>
        </thead>
        <tbody className="bg-white divide-y divide-gray-200">
          {invoices.map((invoice) => (
            <tr key={invoice.id} className="hover:bg-gray-50 transition-colors">
              <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">{invoice.number}</td>
              <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-700">{invoice.customer}</td>
              <td className="px-6 py-4 whitespace-nowrap text-sm font-semibold text-gray-900">${invoice.amount.toFixed(2)}</td>
              <td className="px-6 py-4 whitespace-nowrap">
                <StatusBadge status={invoice.status} />
              </td>
            </tr>
          ))}
          <tr className="bg-gray-50 border-t border-gray-200 font-semibold">
            <td colSpan={4} className="px-6 py-4 text-sm text-right text-gray-700">
              Total: ${totalAmount.toFixed(2)}
            </td>
          </tr>
        </tbody>
      </table>
    </div>
  );
};

export default InvoiceTable;
```

